cd /private/tmp && node -e '
const f=(loc,tz,iso,o={})=>new Intl.DateTimeFormat(loc,{timeZone:tz,hour:"numeric",minute:"2-digit",timeZoneName:"short",...o}).format(new Date(iso));
const cases=[
 ["en-GB","Europe/London","2026-10-23T15:00:00Z"],
 ["en-US","Europe/London","2026-10-23T15:00:00Z"],
 ["en-GB","Europe/London","2026-10-27T15:00:00Z"],
 ["en-US","Europe/London","2026-10-27T15:00:00Z"],
 ["en-IN","Asia/Kolkata","2026-10-27T15:00:00Z"],
 ["en-US","Asia/Kolkata","2026-10-27T15:00:00Z"],
 ["en-GB","Asia/Kolkata","2026-10-27T15:00:00Z"],
 ["en-IE","Europe/Dublin","2026-07-01T15:00:00Z"],
 ["en-IE","Europe/Dublin","2026-01-01T15:00:00Z"],
 ["en-GB","America/New_York","2026-10-23T15:00:00Z"],
 ["en-US","America/New_York","2026-10-23T15:00:00Z"],
 ["en-US","America/Phoenix","2026-10-23T15:00:00Z"],
];
for (const c of cases) console.log(c.join(" | "), "=>", JSON.stringify(f(...c)));
console.log("en-GB h12 =>", JSON.stringify(f("en-GB","Europe/London","2026-10-23T15:00:00Z",{hourCycle:"h12"})));
console.log("en-IN h12 =>", JSON.stringify(f("en-IN","Asia/Kolkata","2026-10-27T15:00:00Z",{hourCycle:"h12"})));
const z=Intl.supportedValuesOf("timeZone");
console.log("lists Asia/Kolkata:", z.includes("Asia/Kolkata"), " lists Asia/Calcutta:", z.includes("Asia/Calcutta"));
console.log("resolved Asia/Kolkata ->", new Intl.DateTimeFormat("en",{timeZone:"Asia/Kolkata"}).resolvedOptions().timeZone);
'

