input.command:
cd /private/tmp && node -e '
const off=(tz,ms)=>new Intl.DateTimeFormat("en-US",{timeZone:tz,timeZoneName:"longOffset"}).formatToParts(new Date(ms)).find(p=>p.type==="timeZoneName").value;
for (const tz of ["Europe/London","America/New_York","America/Los_Angeles"]) {
  const out=[]; let prev=off(tz,Date.UTC(2026,9,20));
  for (let t=Date.UTC(2026,9,20); t<Date.UTC(2027,3,15); t+=3600e3){ const o=off(tz,t); if(o!==prev){out.push(new Date(t).toISOString().slice(0,16)+"Z "+prev+"->"+o); prev=o;} }
  console.log(tz, out.join(" | "));
}'

